; CYCLES_FORWARD_BRANCHES
; AERIA AURORA  -- generated by aurora/gen.py, do not edit.
; The Balloon Shop's aurora (MoreWeather.h, Aurora): the sound (L + R)/2 an octave up -- two
; Hann-windowed taps half a window apart, read twice as fast as written -- through a 500 Hz
; highpass into four delay lines that feed each other (Hadamard), highs damped as they go round,
; 9 s to die away; each line is a curtain with its own place between the speakers and a
; brightness that wanders. The curtains are ADDED to the dry sound.
;
;  knob 0 AMT   the weather's fade 0..127 = 0..1 into the reverb (glided here with the plugin's 1.2 s)
;  knob 1 TIME  decay: T60 = 9 s x 2^((v - 64)/32)     (64 = the plugin's 9 s; 2.25 .. 35 s)
;  knob 2 TONE  damping in the loop, as the plugin's lowpass: 6 kHz x 2^((v - 64)/24) (64 = the plugin). The loop's
;               own lowpass (22.05 kHz) is 7883 Hz x 2^((v - 64)/29.77), held to 13459 Hz (fitted to lose a turn 0.3851 x what the plugin's loses, 2 .. 11.65 kHz): the lines are 0.3851 x as long
;  knob 3 SHFT  0 UNIS, 1 +12 (the plugin's octave), 2 +19, 3 +24: the read runs 1 x .. 4 x the write
;               13 Nov 2026: (L + R) is low-passed first (order 3, elliptic-type, per SHFT; none at UNIS), so the
;               faster read does not fold the top of the sound back down (aliases landing under 8 kHz >= 37 dB down)
;
; HALF RATE (13 Nov 2026): a halfband (polyphase IIR, 5 allpasses) decimates (L + R)/4 to 22.05 kHz; the aurora
; runs a core frame every second frame; a halfband interpolates the curtains back up. Only the halfbands and the
; dry + wet sum run at 44.1 kHz. The wet ends at ~10.5 kHz. Halfband coefficients (A0 | A1): 0.093604 0.557527 0.922692 | 0.315306 0.759827
;
; AMT 0, the glide at 0 and the curtains under 1e-5 for half a second: REST (returns at once,
; output = input bit for bit). Coming up from rest the ring is cleared over 17 dry calls.
; Each call one of the four curtains is looked at in turn (brightness, pan levels, line gain).
; The taps move by whole frames, so nothing is interpolated: exact.
; The lines run at 1/4 of the plugin's level; a rider on what goes into them keeps a long tail of loud sound out of their limit.
;
; X region: 8192 words, base a multiple of 8192: the word X:$213 points to (an X address on this effect)
; The ring is its first 4096 words; the halfbands' block (parity, coefficients, states) is at +$1000.
; One pointer falls a word a core frame; from it: +0 the window (1106 words), then the lines
;   line 0: written at +1106, read at +1627 (521 core frames, 23.6 ms)
;   line 1: written at +1627, read at +2304 (677 core frames, 30.7 ms)
;   line 2: written at +2304, read at +3130 (826 core frames, 37.5 ms)
;   line 3: written at +3130, read at +4095 (965 core frames, 43.8 ms)
; (the plugin's 2703 3523 4282 5014 frames x 0.3851; gains set for the same decay time)
; r7: 00 ST 01 XB 02 RP 03 AMH 04 AML 05 RNG 06 C 07 STEP 08 WW 09 DW 0a SVL 0b SVB 0c INJ 0d WL 0e WR 0f LP0 10 LP1 11 LP2 12 LP3 13 G0 14 G1 15 G2 16 G3 17 CL0 18 CL1 19 CL2 1a CL3 1b CR0 1c CR1 1d CR2 1e CR3 1f CH0 20 CH1 21 CH2 22 CH3 23 CO0 24 CO1 25 CO2 26 CO3 27 CT0 28 CT1 29 CT2 2a CT3 2b CF0 2c CF1 2d CF2 2e CF3 2f QT 30 BLK 31 DAMP 32 RT 33 TLAST 34 OLAST 35 RIDE 36 AR 37 FB 38 FA1 39 FA2 3a FC 3b FP 3c FK 3d FW1 3e FW2 3f FV1

init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #64,>auzero
        move    a,x:(r4)+
auzero:
        nop
        move    x:>$213,r4
        nop
        move    x:(r4),a
        move    a,x:(r7+$01)
        move    a,x:(r7+$02)
        move    #>$00a020,a             ; the plugin's seed
        move    a,x:(r7+$05)
        rts
proc:
        move    x:(r7+$00),a
        tst     a
        bne     auawake
        move    x:(r6),a
        tst     a
        bne     auwake
        rts                             ; REST: nothing touched
auwake:
        move    r7,r4
        move    #>$ffffff,m4
        move    #>$6,n4
        clr     a
        move    (r4)+n4
        do      #58,>auwz
        move    a,x:(r4)+               ; everything from C on: the plugin's reset
auwz:
        nop
        move    #>$400000,a
        move    a,x:(r7+$1f)
        move    a,x:(r7+$20)
        move    a,x:(r7+$21)
        move    a,x:(r7+$22)
        move    a,x:(r7+$27)
        move    a,x:(r7+$28)
        move    a,x:(r7+$29)
        move    a,x:(r7+$2a)
        move    a,x:(r7+$31)
        move    #>$7f0000,a
        move    a,x:(r7+$13)
        move    a,x:(r7+$14)
        move    a,x:(r7+$15)
        move    a,x:(r7+$16)
        move    #>$ffffff,a
        move    a,x:(r7+$33)
        move    a,x:(r7+$34)
        move    #>$7fffff,a
        move    a,x:(r7+$35)
        clr     a
        move    a,x:(r7+$03)
        move    a,x:(r7+$04)
        move    x:(r7+$01),a
        move    a,x:(r7+$02)
        move    #>$000227,a
        move    a,x:(r7+$06)
        move    #>$000003,a             ; the first running call looks at TIME and curtain 0
        move    a,x:(r7+$30)
        move    #>$000011,a
        move    a,x:(r7+$00)
        rts
auawake:
        blt     aurun
; ---- clearing: call n (17 .. 1) clears words (n - 1) * 256 ..
        sub     #>$1,a
        move    a,x:(r7+$00)
        asl     #$8,a,a
        move    x:(r7+$01),x0
        add     x0,a
        move    a1,r4
        move    #>$ffffff,m4
        clr     b
        do      #>$000100,>auclr
        move    b,x:(r4)+
auclr:
        nop
        move    x:(r7+$00),a
        tst     a
        bne     aukeep
        move    #>$ffffff,a             ; cleared: RUN from the next call
        move    a,x:(r7+$00)
; the halfbands' coefficients (their states and the parity are cleared): A1 x 3 at +$1001, A0 x 3 after
        move    x:(r7+$01),a
        add     #>$001001,a
        move    a1,r4
        move    #>$ffffff,m5
        lua     (r4+$06),r5
        do      #3,>auhbc
        move    #>$285bf3,x0
        move    x0,x:(r4)+
        move    #>$614205,x0
        move    x0,x:(r4)+
        move    #>$0bfb37,x0
        move    x0,x:(r5)+
        move    #>$475d10,x0
        move    x0,x:(r5)+
        move    #>$761ac4,x0
        move    x0,x:(r5)+
auhbc:
        nop
aukeep:
        rts
aurun:
; ---- amount: knob / 127, glided with the plugin's 1.2 s (48 bits)
        move    x:(r6),x0
        move    #>$408102,y0
        mpy     y0,x0,a
        asl     a
        move    x:(r7+$03),x0
        sub     x0,a
        move    a,x0
        move    #>$0009e8,y0
        mpy     y0,x0,a
        move    x:(r7+$03),b
        move    x:(r7+$04),b0
        add     a,b
        move    b1,x:(r7+$03)
        move    b0,x:(r7+$04)
        move    x:(r6),a
        tst     a
        bne     auon
        move    x:(r7+$03),a
        cmp     #>$000347,a
        bge     auon
        clr     a                       ; the knob at 0 and the glide under 1e-4: the amount is 0
        move    a,x:(r7+$03)
        move    a,x:(r7+$04)
        move    x:(r7+$2f),a
        cmp     #>$000562,a
        blt     auon
        clr     a                       ; and the curtains quiet for half a second: REST
        move    a,x:(r7+$00)
        rts
auon:
; ---- what goes into the lines this call: the amount x the rider (1 unless the lines stack up near full scale)
        move    x:(r7+$03),x0
        move    x:(r7+$35),y0
        mpy     y0,x0,a
        move    a,x:(r7+$36)
; ---- SHFT: frames the taps move a frame; UNIS parks tap 1 at the window's top
        move    x:(r6+$3),a
        asr     #$10,a,a
        move    a1,a
        move    #>$3,x0
        cmp     x0,a
        tgt     x0,a
        move    a,x:(r7+$07)
        bsr     >auzaa                  ; the anti-alias low-pass for this SHFT
        move    x:(r7+$07),a
        tst     a
        bne     aumove
        move    #>$000227,a
        move    a,x:(r7+$06)
aumove:
; ---- the window's weight at the END of this call, ramped to over its 16 frames
        move    x:(r7+$07),a
        asl     #$3,a,a                 ; 8 core frames a call
        move    a1,x0
        move    x:(r7+$06),a
        sub     x0,a
        bge     auwin
        add     #>$00044e,a
        tst     a
        bge     auwin
        add     #>$00044e,a
auwin:
        asl     #$c,a,a
        move    a,x0
        move    #>$76f0ab,y0
        mpy     y0,x0,a
        asl     a                       ; phase = c / window
        sub     #>$400000,a
        abs     a
        asl     #$2,a,a
        neg     a
        add     #>$7fffff,a
        move    a,x0                    ; 1 - |4 phase - 2|
        bsr     ausin
        add     #>$400000,a             ; sin^2(pi phase)
        move    x:(r7+$08),b
        sub     b,a
        asr     #$3,a,a
        move    a,x:(r7+$09)
; ---- one job a call: curtain BLK & 3 (and, with curtain 0 / 1, the TIME / TONE knob if it moved)
        move    x:(r7+$30),a
        add     #>$1,a
        and     #>$000003,a
        move    a1,x:(r7+$30)
        tst     a
        bne     aunot0
        move    x:(r6+$1),a
        move    x:(r7+$33),x0
        cmp     x0,a
        beq     aucur0
        move    a,x:(r7+$33)
        asr     #$3,a,a                 ; (v/32)/32
        move    a1,a
        bsr     auexp
        move    b,x0
        move    x0,x:(r7+$32)                 ; 2^-(v/32): 1/T60 against TIME 0's
        bra     aucur0
aunot0:
        cmp     #>$000001,a
        bne     aunot1
        move    x:(r6+$2),a
        move    x:(r7+$34),x0
        cmp     x0,a
        beq     aucur1
        move    a,x:(r7+$34)
        move    #>$7f0000,b
        sub     a,b
        move    b,x0
        move    #>$113358,y0
        mpy     y0,x0,a                 ; ((127 - v)/24)/32
        bsr     auexp
        move    b,x0
        move    #>$383537,y0
        mpy     y0,x0,a                 ; w / (32 ln 2)
        move    #>$1621d2,x0
        cmp     x0,a
        tgt     x0,a
        bsr     auexp
        move    #>$7fffff,a
        sub     b,a
        move    a,x:(r7+$31)                ; 1 - e^-w
        bra     aucur1
aunot1:
        cmp     #>$000002,a
        beq     aucur2
        bra     aucur3
aucur0:
        lua     (r7+$0),r4           ; curtain 0
        move    #>$561a3f,x1
        move    #>$1be628,y1
        move    #>$006b2b,n4
        bra     aucurc
aucur1:
        lua     (r7+$1),r4           ; curtain 1
        move    #>$49ba34,x1
        move    #>$348010,y1
        move    #>$008b41,n4
        bra     aucurc
aucur2:
        lua     (r7+$2),r4           ; curtain 2
        move    #>$348010,x1
        move    #>$49ba34,y1
        move    #>$00a9e7,n4
        bra     aucurc
aucur3:
        lua     (r7+$3),r4           ; curtain 3
        move    #>$1be628,x1
        move    #>$561a3f,y1
        move    #>$00c67e,n4
aucurc:
; the curtain (r4 = r7 + its number; x1 y1 = its pan levels / 2, n4 its decay constant): its brightness wanders
; to a new place every 2 .. 7 s
        move    #>$ffffff,m4
        move    x:(r4+$2b),a
        sub     #>$1,a
        move    a,x:(r4+$2b)
        bgt     auheld
        bsr     aurand
        move    #>$000d75,y0
        mpy     y0,x0,a
        add     #>$000562,a
        move    a,x:(r4+$2b)
        bsr     aurand
        move    x0,x:(r4+$27)
auheld:
        move    x:(r4+$27),a
        move    x:(r4+$1f),x0
        sub     x0,a
        move    a,x0
        move    #>$001fb0,y0
        mpy     y0,x0,a
        move    x:(r4+$1f),b
        move    x:(r4+$23),b0
        add     a,b
        move    b1,x:(r4+$1f)
        move    b0,x:(r4+$23)
; its level on each side, halved (the curtain sums go to the interpolator at half): 0.45 (0.2 + 0.8 brightness) x the pan / 2
        move    b1,x0
        move    #>$2e147b,y0
        mpy     y0,x0,a
        add     #>$0b851f,a
        move    a,x0
        mpy     x1,x0,a
        move    a,x:(r4+$17)
        mpy     x0,y1,a
        move    a,x:(r4+$1b)
; its line's gain for the decay time: 2^-(K len / T60)
        move    x:(r7+$32),x0
        move    n4,y0
        mpy     y0,x0,a
        bsr     auexp
        move    b,x0
        move    x0,x:(r4+$13)
aucurd:
; ======== the frames (44.1 kHz): the halfbands around a 22.05 kHz core frame every odd frame ========
        move    #>$000fff,m1
        move    x:(r7+$02),r1
        move    #>$1,n0
        move    x:(r7+$01),a
        add     #>$001000,a
        move    a1,r2  ; the halfbands' block
        move    #>$ffffff,m2
        move    #>$ffffff,m3
        move    #>$ffffff,m5
        move    #>$12,n2  ; x:(r2+n2): the decimator's A1 output
        lua     (r2+$07),r5  ; (an odd first frame: the pointers where an even frame leaves them)
        lua     (r2+$19),r3
        do      n7,>auframes
        bchg    #0,x:(r2)  ; the pair's parity (C = it before the change): 0 = the first (even) frame, 1 = the second (the core runs)
        bcs     auodd
; even: the decimator's A1 path takes this frame; out: the interpolator's A1 paths on the last core frame
        lua     (r2+$01),r5
        lua     (r2+$10),r3
        move    x:(r0+n0),x0
        move    x:(r0),a
        add     x0,a x:(r5)+,y0  ; L + R; the first coefficient
        asr     a x:(r3),b  ; the first state
        asr     a
        move    a,x0  ; (L + R)/4
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r5)+,y0  ; its output; the interpolator's first coefficient
        move    a,x:(r3)+  ; s[K]: the output (the odd frame reads it)
        move    x:(r3),b  ; the interpolator's first state
        move    x:(r7+$0d),x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r0),x0  ; its output; x0 = the dry
        move    a,x:(r3)+  ; s[K]
        asl     #$3,a,a  ; x 4 (the lines' scale) x 2 (the halved levels)
        add     x0,a x:(r5)+,y0  ; the next path's first coefficient
        move    a,x:(r0)+  ; dry + wet
        move    x:(r3),b  ; the next path's first state
        move    x:(r7+$0e),x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r0),x0  ; its output; x0 = the dry
        move    a,x:(r3)+  ; s[K]
        asl     #$3,a,a  ; x 4 (the lines' scale) x 2 (the halved levels)
        add     x0,a
        move    a,x:(r0)+  ; dry + wet
        bra     aufnx
auodd:
; odd (r5, r3 where the even frame left them): the decimator's A0 path; d = (A0 + A1)/2; the core frame; out: the interpolator's A0 paths
        move    x:(r0+n0),x0
        move    x:(r0),a
        add     x0,a x:(r5)+,y0  ; L + R; the first coefficient
        asr     a x:(r3),b  ; the first state
        asr     a
        move    a,x0  ; (L + R)/4
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r5)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r2+n2),x0  ; its output; x0 = the A1 path's (the even frame)
        move    b,x:(r3)+
        add     x0,b
        asr     b
        move    b,x0  ; d: the decimated (L + R)/4
; anti-alias low-pass on d (per SHFT; UNIS: B = 1, the rest 0 = d): the window holds y/2
; w = B d + 2 A1H w1 + A2 w2;  u = w + 2 CH w1 + K w2;  v = u + P v1;  y/2 = v + K v1
        move    x:(r7+$37),y0
        mpy     y0,x0,a
        move    x:(r7+$3d),x1
        move    x:(r7+$38),y0
        mac     x1,y0,a
        mac     x1,y0,a
        move    x:(r7+$3e),x0
        move    x:(r7+$39),y0
        macr    y0,x0,a
        move    x1,x:(r7+$3e)
        move    a,x:(r7+$3d)
        move    x:(r7+$3a),y0
        mac     x1,y0,a
        mac     x1,y0,a
        move    x:(r7+$3c),y1
        mac     x0,y1,a
        move    x:(r7+$3f),x1
        move    x:(r7+$3b),y0
        macr    x1,y0,a
        move    a,x:(r7+$3f)
        macr    y1,x1,a
        move    a,x:(r1)
; the taps: c core frames (+ 2) back and half a window further round; c falls STEP a core frame
        move    x:(r7+$06),a
        move    x:(r7+$07),x0
        sub     x0,a
        bge     autapc
        add     #>$00044e,a
autapc:
        move    a1,x:(r7+$06)
        add     #>$000002,a
        move    a1,n1
        add     #>$000227,a
        move    x:(r1+n1),x0
        cmp     #>$000450,a
        blt     autaph
        sub     #>$00044e,a
autaph:
        move    a1,n1
        move    x:(r7+$08),b
        move    x:(r1+n1),x1
        move    x:(r7+$09),y0
        add     y0,b
        move    b,x:(r7+$08)
        move    b,y0
; y/4 = tap2/2 + w (tap1 - tap2)/2 (the window holds y/2)
        move    x0,a
        sub     x1,a
        asr     a
        move    a,x0
        mpy     y0,x0,a
        move    x1,b
        asr     b
        add     b,a
; 500 Hz highpass (state variable, on y/4): lp += f bp; hp = x - lp - q bp; bp += f hp
        move    x:(r7+$0b),x0
        move    #>$1238b3,y0
        move    x:(r7+$0a),b
        macr    y0,x0,b
        move    b,x:(r7+$0a)
        sub     b,a
        move    #>$5a85f9,y1
        mac     -x0,y1,a
        macr    -x0,y1,a
        move    a,x1
        move    x:(r7+$0b),b
        macr    x1,y0,b
        move    b,x:(r7+$0b)
; into the lines: +-(up x amount)/2, at the lines' 1/4 scale (hp is on y/4: one shift fewer than LSHIFT)
        move    x:(r7+$36),y0
        mpy     x1,y0,a
        asr     #$1,a,a
        rnd     a
        move    a,x:(r7+$0c)
; the curtains: each line's output to its place
        clr     a
        clr     b
        move    #>$00065b,n1
        move    x:(r7+$17),y0
        move    x:(r1+n1),x0
        mac     y0,x0,a
        move    x:(r7+$1b),y0
        mac     y0,x0,b
        move    #>$000900,n1
        move    x:(r7+$18),y0
        move    x:(r1+n1),x0
        mac     y0,x0,a
        move    x:(r7+$1c),y0
        mac     y0,x0,b
        move    #>$000c3a,n1
        move    x:(r7+$19),y0
        move    x:(r1+n1),x0
        mac     y0,x0,a
        move    x:(r7+$1d),y0
        mac     y0,x0,b
        move    #>$000fff,n1
        move    x:(r7+$1a),y0
        move    x:(r1+n1),x0
        mac     y0,x0,a
        move    x:(r7+$1e),y0
        mac     y0,x0,b
        move    a,x:(r7+$0d)                  ; (the curtains' levels are halved: WL, WR = the sums / 2)
        move    b,x:(r7+$0e)
; the highs damped as they go round
        move    x:(r7+$31),y1
        move    #>$00065b,n1
        move    x:(r7+$0f),b
        move    x:(r1+n1),a
        sub     b,a
        move    a,x1
        macr    y1,x1,b
        move    b,x:(r7+$0f)
        move    #>$000900,n1
        move    x:(r7+$10),b
        move    x:(r1+n1),a
        sub     b,a
        move    a,x1
        macr    y1,x1,b
        move    b,x:(r7+$10)
        move    #>$000c3a,n1
        move    x:(r7+$11),b
        move    x:(r1+n1),a
        sub     b,a
        move    a,x1
        macr    y1,x1,b
        move    b,x:(r7+$11)
        move    #>$000fff,n1
        move    x:(r7+$12),b
        move    x:(r1+n1),a
        sub     b,a
        move    a,x1
        macr    y1,x1,b
        move    b,x:(r7+$12)
; Hadamard: h0 h1 h2 h3 = (l0 +- l1 +- l2 +- l3)/2
        move    x:(r7+$0f),a
        move    x:(r7+$10),x0
        add     x0,a
        asr     a
        rnd     a
        move    a,x1
        move    x:(r7+$0f),b
        sub     x0,b
        asr     b
        rnd     b
        move    b,y1
        move    x:(r7+$11),a
        move    x:(r7+$12),x0
        add     x0,a
        asr     a
        rnd     a
        move    x:(r7+$11),b
        sub     x0,b
        asr     b
        rnd     b
        move    a,x0
        move    b,y0
        move    x1,a
        add     x0,a                    ; h0
        move    x1,b
        sub     x0,b                    ; h2
        move    a,x1
        move    x:(r7+$13),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        add     x0,a
        move    #>$000452,n1
        move    a,x:(r1+n1)
        move    b,x1
        move    x:(r7+$15),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        add     x0,a
        move    #>$000900,n1
        move    a,x:(r1+n1)
        move    y1,a
        add     y0,a                    ; h1
        move    y1,b
        sub     y0,b                    ; h3
        move    a,x1
        move    x:(r7+$14),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        sub     x0,a
        move    #>$00065b,n1
        move    a,x:(r1+n1)
        move    b,x1
        move    x:(r7+$16),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        sub     x0,a
        move    #>$000c3a,n1
        move    a,x:(r1+n1)
        move    (r1)-
; out: the interpolator's A0 paths on this core frame's curtains
        move    x:(r7+$0d),x0
        move    x:(r5)+,y0
        move    x:(r3),b
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r5)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r0),x0  ; its output; x0 = the dry
        move    b,x:(r3)+  ; s[K]
        asl     #$3,b,b  ; x 4 (the lines' scale) x 2 (the halved levels)
        add     x0,b x:(r5)+,y0  ; the next path's first coefficient
        move    b,x:(r0)+  ; dry + wet
        move    x:(r3),b  ; the next path's first state
        move    x:(r7+$0e),x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r5)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r5)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r0),x0  ; its output; x0 = the dry
        move    b,x:(r3)+  ; s[K]
        asl     #$3,b,b  ; x 4 (the lines' scale) x 2 (the halved levels)
        add     x0,b
        move    b,x:(r0)+  ; dry + wet
aufnx:
        nop       ; (the loop's last instruction)
auframes:
        nop
        move    r1,x:(r7+$02)
        move    #>$ffffff,m1
; the rider: the largest of the four lines' damped reads (the last frame) over 0.4 of the line scale rides the
; injection down 1/4 a call; under it the rider comes back 2^-10 a call. A long TIME on loud sound
; can no longer stack the lines into their limit (the plugin's float lines would only grow)
        move    x:(r7+$0f),a
        abs     a
        move    x:(r7+$10),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        move    x:(r7+$11),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        move    x:(r7+$12),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        cmp     #>$333333,a
        move    x:(r7+$35),b
        ble     aurok
        move    b,x0
        move    #>$200000,y0
        mpy     y0,x0,a
        sub     a,b
        bra     aurset
aurok:
        move    #>$7fffff,a
        sub     b,a
        asr     #$a,a,a
        add     a,b
aurset:
        move    b,x:(r7+$35)
; quiet? (the last frame's curtains, both sides, against 512 LSB)
        move    x:(r7+$0d),a
        abs     a
        move    x:(r7+$0e),b
        abs     b
        add     b,a
        asl     #$3,a,a
        cmp     #>$000200,a
        ble     auquiet
        clr     a
        move    a,x:(r7+$2f)
        rts
auquiet:
        move    x:(r7+$2f),a
        cmp     #>$000562,a
        bge     auqx
        add     #>$1,a
        move    a,x:(r7+$2f)
auqx:
        rts
; ---- subroutines (after their callers) ----
; the anti-alias low-pass coefficients for this SHFT: B A1H A2 CH P K (see gen.py aa_coefs)
auzaa:
        move    x:(r7+$07),a
        cmp     #>$000000,a
        bne     auzb12
        move    #>$7fffff,x0
        move    x0,x:(r7+$37)
        move    #>$000000,x0
        move    x0,x:(r7+$38)
        move    #>$000000,x0
        move    x0,x:(r7+$39)
        move    #>$000000,x0
        move    x0,x:(r7+$3a)
        move    #>$000000,x0
        move    x0,x:(r7+$3b)
        move    #>$000000,x0
        move    x0,x:(r7+$3c)
        rts
auzb12:
        cmp     #>$000001,a
        bne     auzb19
        move    #>$09c530,x0
        move    x0,x:(r7+$37)
        move    #>$2e6b8f,x0
        move    x0,x:(r7+$38)
        move    #>$a9ab95,x0
        move    x0,x:(r7+$39)
        move    #>$42da7a,x0
        move    x0,x:(r7+$3a)
        move    #>$4151ac,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
auzb19:
        cmp     #>$000002,a
        bne     auzb24
        move    #>$04d145,x0
        move    x0,x:(r7+$37)
        move    #>$5624ba,x0
        move    x0,x:(r7+$38)
        move    #>$9e6df3,x0
        move    x0,x:(r7+$39)
        move    #>$f21bae,x0
        move    x0,x:(r7+$3a)
        move    #>$56bbb3,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
auzb24:
        move    #>$02d9a1,x0
        move    x0,x:(r7+$37)
        move    #>$66bd9b,x0
        move    x0,x:(r7+$38)
        move    #>$9707c2,x0
        move    x0,x:(r7+$39)
        move    #>$c7958f,x0
        move    x0,x:(r7+$3a)
        move    #>$624fb9,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
aurand:
        move    x:(r7+$05),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a                       ; a1:a0 = the whole product, a0 its low 24 bits
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$05)
        move    a1,b
        lsr     b
        move    b1,x0
        move    x0,a
        rts
auexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>aupow
        asr     b
aupow:
        asl     b
        rts
ausin:
        mpy     x0,x0,a
        move    a,x1                    ; u^2
        move    #>$04a277,y0
        mpy     x1,y0,a
        add     #>$d6de19,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$648200,a
        move    a,y0
        mpy     y0,x0,a                 ; 0.5 sin(pi u / 2)
        rts
